steps.text:
/*
	VIOC_enemy_roadblocks.sqf - agregado por tools/vio_build.py (parche enemy_roadblocks; copia configurada, no es del autor
	de la mision). init.sqf lo lanza en todas las maquinas: el servidor levanta los bloqueos y cada cliente enciende el
	fuego (efectos locales) de los que tiene cerca.

	Bloqueos de carretera de la IA ENEMIGA (Oeste/Este sin jugadores) en las entradas de sus pueblos del FRENTE:
	  - Pueblos: del bando enemigo desde hace VIOC_RB_DELAY s (3 min), no de retaguardia (front_line) y no la capital (ya
	    tiene sus controles, towns_capital). Primero los que te quito a ti (pueblos, aerodromos, sitios militares) y despues
	    los mas cercanos a un jugador; como mucho VIOC_RB_MAX_TOWNS pueblos con bloqueos a la vez. Nunca se levantan con un
	    jugador a menos de VIOC_RB_BUILD_FREE m del centro del pueblo.
	  - Cada bloqueo (VIOC_ENEMY_ROADBLOCKS por pueblo: 2 o 3) va en un camino que entra al pueblo a 280-450 m del centro
	    (los mismos lugares que los controles de la capital, VIOC_TC_fnc_cpSpots): barreras y vallas del estilo del duenio
	    en las banquinas, cartel y bandera, neumaticos y un coche destrozado y ARDIENDO (llamas, humo y luz) que cierra un
	    carril (solo en caminos de 6 m o mas; en los estrechos, sin coche). El otro carril queda libre a proposito: si se cierra del todo, los vehiculos de la IA (de los dos bandos) se
	    atascan. Se pasa a pie o despacio por el carril libre.
	  - Si un vehiculo de la IA (sin jugadores dentro) que intenta moverse lleva VIOC_RB_STUCK s sin avanzar 3 m a menos de
	    12 m del coche, se quita el coche de ese bloqueo (la IA despeja el paso), sin jugadores cerca ni mirando.
	  - Al perder el pueblo el bando que los puso (o pasar a retaguardia) se quitan, cada uno cuando ningun jugador esta a
	    menos de 300 m ni lo ve (VIOC_RB_fnc_hidden). Se levantan sin jugadores a VIOC_RB_BUILD_CP m de cada bloqueo; los
	    que no se pudieron (alguien encima o cerca) se reintentan cada VIOC_RB_RETRY s. Nunca a menos de 500 m de un
	    pueblo tuyo.
	  - Aviso a tu bando cuando el enemigo bloquea las entradas de un pueblo que te quito.
	No se guardan: al cargar una partida se vuelven a levantar en los pueblos que cumplan (a los 3 min).
	Parametro VIOC_ENEMY_ROADBLOCKS (0 no, 2 o 3 por pueblo). Necesita towns_capital (sus funciones de controles).
	Consola (LOCAL EXEC en el anfitrion): hint (call VIOC_RB_fnc_info);   call VIOC_RB_fnc_markers;   (marcadores locales)
*/
if (!isNil "VIOC_RB_RUNNING") exitWith {};
VIOC_RB_RUNNING = true;
VIOC_RB_N = missionNamespace getVariable ["VIOC_ENEMY_ROADBLOCKS", 2];
if !(VIOC_RB_N isEqualType 0) then {VIOC_RB_N = 2};
if (VIOC_RB_N <= 0) exitWith {diag_log "[VIOC enemy_roadblocks] desactivado por el parametro de lobby"};

//--- ---------------------------------- cliente: fuego de los coches ----------------------------------
//--- VIOC_RB_BURN (lo publica el servidor) = coches de los bloqueos. Llamas, humo y luz son efectos locales que se
//--- encienden a menos de 1500 m de la camara y se apagan a mas de 2000 m o al quitarse el coche.
if (hasInterface) then {
	[] spawn {
		waitUntil {sleep 1; !isNull player};
		VIOC_RB_FX = [];
		while {true} do {
			private _list = missionNamespace getVariable ["VIOC_RB_BURN", []];
			if !(_list isEqualType []) then {_list = []};
			private _cam = positionCameraToWorld [0, 0, 0];
			VIOC_RB_FX = VIOC_RB_FX select {
				private _w = _x select 0;
				private _keep = (!isNull _w) && {_w in _list} && {(_w distance2D _cam) < 2000};
				if (!_keep) then {{deleteVehicle _x} forEach (_x select 1)};
				_keep
			};
			{
				private _w = _x;
				if ((!isNull _w) && {(_w distance2D _cam) < 1500} && {(VIOC_RB_FX findIf {(_x select 0) isEqualTo _w}) < 0}) then {
					private _p = getPosATL _w;
					private _fx = [];
					{
						if (isClass (configFile >> "CfgCloudlets" >> _x)) then {
							private _s = "#particlesource" createVehicleLocal _p;
							_s setParticleClass _x;
							_s setPosATL _p;
							_fx pushBack _s;
						};
					} forEach ["MediumDestructionFire", "MediumDestructionSmoke"];
					private _l = "#lightpoint" createVehicleLocal (_p vectorAdd [0, 0, 1.5]);
					_l setLightBrightness 1.2;
					_l setLightColor [1, 0.45, 0.15];
					_l setLightAmbient [1, 0.35, 0.1];
					_fx pushBack _l;
					VIOC_RB_FX pushBack [_w, _fx];
				};
			} forEach _list;
			sleep 3;
		};
	};
};

if (!isServer) exitWith {};

//--- Ajustes
VIOC_RB_DELAY = 180;          // s del bando enemigo antes de levantar los bloqueos
VIOC_RB_MAX_TOWNS = 8;        // pueblos con bloqueos a la vez
VIOC_RB_BUILD_FREE = 600;     // m sin jugadores alrededor del centro del pueblo para levantarlos
VIOC_RB_STUCK = 40;           // s de un vehiculo de la IA parado junto al coche antes de quitarlo
VIOC_RB_PERIOD = 10;          // s por pasada
VIOC_RB_WRECKS = ["Land_Wreck_Car_F", "Land_Wreck_Car2_F", "Land_Wreck_Car3_F", "Land_Wreck_Offroad_F", "Land_Wreck_Offroad2_F"];	//--- solo coches (los camiones no dejan el carril libre)
VIOC_RB_BUILD_CP = 500;       // m sin jugadores alrededor de cada bloqueo para levantarlo
VIOC_RB_RETRY = 60;           // s entre reintentos de los bloqueos que no se pudieron levantar

VIOC_RB_LIST = [];            // HashMap por pueblo: town, sid, cps (levantados), todo (por levantar), retry, from, told, gone
VIOC_RB_OWN = [];             // [pueblo, sideID, desde, sideID anterior]
VIOC_RB_BURN = [];
VIOC_RB_HUM = [];             // bandos que alguna vez tuvieron un jugador (no se olvidan si nadie esta conectado)
VIOC_RB_INFO = [0, 0, 0];     // [bloqueos levantados, coches quitados (IA atascada), bloqueos quitados]

//--- ---------------------------------- utilidades ----------------------------------
VIOC_RB_fnc_humans = {
	private _pl = allPlayers - (entities "HeadlessClient_F");
	if (!isMultiplayer && {hasInterface} && {!isNull player}) then {_pl pushBackUnique player};
	{
		private _s = side group _x;
		if (_s in [west, east]) then {VIOC_RB_HUM pushBackUnique _s};
	} forEach _pl;
	VIOC_RB_HUM
};

//--- [posicion, jugadores] -> true si ningun jugador esta a menos de 300 m ni lo ve a menos de 1200 m
VIOC_RB_fnc_hidden = {
	params ["_p", "_pl"];
	private _asl = (AGLToASL [_p select 0, _p select 1, 0]) vectorAdd [0, 0, 1.5];
	(_pl findIf {
		private _d = _x distance2D _p;
		(_d < 300) || {(_d < 1200) && {([vehicle _x, "VIEW", objNull] checkVisibility [eyePos _x, _asl]) > 0.2}}
	}) < 0
};

VIOC_RB_fnc_players = {
	private _pl = (allPlayers - (entities "HeadlessClient_F")) select {alive _x};
	if (!isMultiplayer && {hasInterface} && {!isNull player} && {alive player}) then {_pl pushBackUnique player};
	_pl
};

//--- [posicion, radio, jugadores] -> true si alguno esta mas cerca
VIOC_RB_fnc_near = {
	params ["_p", "_r", "_pl"];
	(_pl findIf {(_x distance2D _p) < _r}) >= 0
};

VIOC_RB_fnc_rear = {
	params ["_t"];
	!isNil "VIOC_FL_fnc_isRear" && {[_t] call VIOC_FL_fnc_isRear}
};

//--- [control] -> coche destrozado que cierra un carril: atravesado en caminos de 7 m o mas, a lo largo en los de 6-7 m
//--- y ninguno en los mas estrechos. Siempre de su lado de la mitad del camino (a 0.4 m de ella como minimo), segun su
//--- tamanio real: el otro carril queda libre (3 m o mas).
VIOC_RB_fnc_wreck = {
	params ["_cp"];
	private _cls = VIOC_RB_WRECKS select {isClass (configFile >> "CfgVehicles" >> _x)};
	if (count _cls == 0) exitWith {objNull};
	private _p = _cp get "pos";
	private _dir = _cp get "dir";
	private _w = _cp get "w";
	if (_w < 6) exitWith {objNull};
	private _wide = _w >= 7;
	private _sgn = selectRandom [1, -1];
	private _probe = [_p, _dir, _sgn * 2, 14] call VIOC_TC_fnc_lw;
	if (surfaceIsWater _probe) exitWith {objNull};
	if !(((_probe nearEntities [["Man", "LandVehicle", "Air", "Ship"], 9]) select {alive _x}) isEqualTo []) exitWith {objNull};
	private _o = createVehicle [selectRandom _cls, [0, 0, 0], [], 0, "CAN_COLLIDE"];
	if (isNull _o) exitWith {objNull};
	(boundingBoxReal _o) params ["_b1", "_b2"];
	private _bx = ((_b2 select 0) - (_b1 select 0)) max 1;
	private _by = ((_b2 select 1) - (_b1 select 1)) max 1;
	private _len = _bx max _by;
	private _wid = _bx min _by;
	private _rel = if (_wide) then {(random 30) - 15} else {random 8};	//--- grados respecto de atravesado / de a lo largo
	//--- ancho que ocupa a lo ancho del camino
	private _across = if (_wide) then {(_len * (abs (cos _rel))) + (_wid * (abs (sin _rel)))} else {(_wid * (abs (cos _rel))) + (_len * (abs (sin _rel)))};
	private _q = [_p, _dir, _sgn * (0.4 + (_across / 2)), 14] call VIOC_TC_fnc_lw;
	//--- el eje largo del modelo puede ser x o y: el giro lo pone atravesado o a lo largo segun haga falta
	private _base = if (_by >= _bx) then {_dir} else {_dir + 90};
	_o setDir (if (_wide) then {_base + 90 + _rel} else {_base + _rel});
	_o setPosATL _q;
	_o setVectorUp (surfaceNormal _q);
	_o setVariable ["VIOC_KEEP", true];
	_o setVariable ["vioc_rb", true];
	_cp set ["wsgn", _sgn];
	_o
};

//--- [control, sideID, jugadores] -> true si se levanto (false con un jugador a menos de VIOC_RB_BUILD_CP m o alguien o
//--- algun vehiculo encima: se reintenta despues)
VIOC_RB_fnc_build = {
	params ["_cp", "_sid", ["_pl", []]];
	private _p = _cp get "pos";
	if ([_p, VIOC_RB_BUILD_CP, _pl] call VIOC_RB_fnc_near) exitWith {false};
	private _near = (_p nearEntities [["Man", "LandVehicle", "Air", "Ship"], VIOC_TC_CP_BLOCK]) select {alive _x && {!(_x isKindOf "StaticWeapon")}};
	if (count _near > 0) exitWith {false};
	private _style = [_sid] call VIOC_TC_fnc_style;
	private _dir = _cp get "dir";
	private _h = (_cp get "w") / 2;
	private _tex = missionNamespace getVariable [format ["CTI_%1FLAG", (_sid) call CTI_CO_FNC_GetSideFromID], ""];
	private _props = [];
	{
		_x params ["_role", "_sgn", "_xe", "_y0", "_rel", "_shoulder"];
		private _cls = _style getOrDefault [_role, ""];
		if (_cls != "") then {
			private _o = [_cls, _p, _dir, _h, _sgn, _xe, _y0, _rel, _shoulder] call VIOC_TC_fnc_place;
			if (!isNull _o) then {
				if (_role == "flag") then {
					if (_tex isEqualType "" && {_tex != ""}) then {_o setFlagTexture _tex};
				} else {
					_o enableSimulationGlobal false;
					if (_role == "wall") then {_o allowDamage false};
				};
				_o setVariable ["vioc_rb", true];
				_props pushBack _o;
			};
		};
	} forEach VIOC_TC_CP_LAYOUT;
	private _wr = [_cp] call VIOC_RB_fnc_wreck;
	//--- neumaticos en la banquina del lado del coche
	if (!isNull _wr && {isClass (configFile >> "CfgVehicles" >> "Land_Tyres_F")}) then {
		private _o = ["Land_Tyres_F", _p, _dir, _h, _cp getOrDefault ["wsgn", 1], 1, 13, 0, true] call VIOC_TC_fnc_place;
		if (!isNull _o) then {_o enableSimulationGlobal false; _o setVariable ["vioc_rb", true]; _props pushBack _o};
	};
	_cp set ["props", _props];
	_cp set ["wreck", _wr];
	_cp set ["stk", 0];
	VIOC_RB_INFO set [0, (VIOC_RB_INFO select 0) + 1];
	true
};

VIOC_RB_fnc_clearCp = {
	params ["_cp"];
	{if (!isNull _x) then {deleteVehicle _x}} forEach (_cp getOrDefault ["props", []]);
	private _w = _cp getOrDefault ["wreck", objNull];
	if (!isNull _w) then {deleteVehicle _w};
	_cp set ["props", []];
	_cp set ["wreck", objNull];
	VIOC_RB_INFO set [2, (VIOC_RB_INFO select 2) + 1];
};

VIOC_RB_fnc_info = {
	private _l = [format ["Bloqueos enemigos: %1 pueblos; levantados %2, coches quitados por IA atascada %3, quitados %4", count VIOC_RB_LIST, VIOC_RB_INFO select 0, VIOC_RB_INFO select 1, VIOC_RB_INFO select 2]];
	{
		_l pushBack format ["%1: %2 bloqueos%3%4", (_x get "town") getVariable ["cti_town_name", "?"], count (_x get "cps"), ["", " (te lo quito a ti)"] select (_x get "from"), ["", " (quitandose)"] select (_x getOrDefault ["gone", false])];
	} forEach VIOC_RB_LIST;
	_l joinString "\n"
};

//--- Marcadores locales de los bloqueos (prueba; en la maquina que lo ejecuta)
VIOC_RB_fnc_markers = {
	{deleteMarkerLocal _x} forEach (allMapMarkers select {(_x find "vioc_rb_mk_") == 0});
	private _n = 0;
	{
		{
			_n = _n + 1;
			private _m = createMarkerLocal [format ["vioc_rb_mk_%1", _n], _x get "pos"];
			_m setMarkerTypeLocal "mil_warning";
			_m setMarkerColorLocal "ColorOrange";
			_m setMarkerTextLocal "Bloqueo";
		} forEach (_x get "cps");
	} forEach VIOC_RB_LIST;
	_n
};

//--- ---------------------------------- bucle ----------------------------------
waitUntil {sleep 2; !isNil "CTI_Init_Server" && {!isNil "CTI_InitTowns"}};
private _t0 = time + 180;
waitUntil {sleep 2; !isNil "VIOC_TC_fnc_cpTick" || {time > _t0}};
if (isNil "VIOC_TC_fnc_cpSpots" || {isNil "VIOC_TC_fnc_place"} || {isNil "VIOC_TC_fnc_style"} || {isNil "VIOC_TC_CP_LAYOUT"}) exitWith {diag_log "[VIOC enemy_roadblocks] sin las funciones de towns_capital: nada que hacer"};
diag_log format ["[VIOC enemy_roadblocks] activo: %1 bloqueos por pueblo, hasta %2 pueblos", VIOC_RB_N, VIOC_RB_MAX_TOWNS];

while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
	private _hum = call VIOC_RB_fnc_humans;
	private _hids = _hum apply {_x call CTI_CO_FNC_GetSideID};
	private _eids = [CTI_WEST_ID, CTI_EAST_ID] - _hids;
	private _pl = call VIOC_RB_fnc_players;
	private _towns = missionNamespace getVariable ["CTI_Towns", []];

	//--- duenio de cada pueblo y desde cuando (y el anterior: para saber si te lo quitaron a ti)
	{
		private _t = _x;
		private _sid = _t getVariable ["cti_town_sideID", -1];
		private _i = VIOC_RB_OWN findIf {(_x select 0) isEqualTo _t};
		if (_i < 0) then {
			VIOC_RB_OWN pushBack [_t, _sid, time, -1];
		} else {
			if (((VIOC_RB_OWN select _i) select 1) != _sid) then {VIOC_RB_OWN set [_i, [_t, _sid, time, (VIOC_RB_OWN select _i) select 1]]};
		};
	} forEach _towns;

	//--- quitar los de pueblos que ya no cumplen (cada bloqueo cuando ningun jugador esta cerca ni lo ve)
	{
		private _e = _x;
		private _t = _e get "town";
		private _bad = (isNull _t) || {(_t getVariable ["cti_town_sideID", -1]) != (_e get "sid")} || {!((_e get "sid") in _eids)} || {[_t] call VIOC_RB_fnc_rear};
		_e set ["gone", _bad];
		if (_bad) then {
			_e set ["todo", []];
			private _left = [];
			{
				if ([_x get "pos", _pl] call VIOC_RB_fnc_hidden) then {[_x] call VIOC_RB_fnc_clearCp} else {_left pushBack _x};
			} forEach (_e get "cps");
			_e set ["cps", _left];
		};
	} forEach VIOC_RB_LIST;
	VIOC_RB_LIST = VIOC_RB_LIST select {!(_x get "gone") || {count (_x get "cps") > 0}};

	//--- [entrada, bandos humanos]: intenta levantar los bloqueos pendientes; aviso la primera vez si te lo quito a ti
	private _fnc_try = {
		params ["_e", "_hum", "_pl"];
		private _todo = [];
		{
			if ([_x, _e get "sid", _pl] call VIOC_RB_fnc_build) then {(_e get "cps") pushBack _x} else {_todo pushBack _x};
		} forEach (_e get "todo");
		_e set ["todo", _todo];
		_e set ["retry", time + VIOC_RB_RETRY];
		if ((_e get "from") && {!(_e get "told")} && {count (_e get "cps") > 0}) then {
			_e set ["told", true];
			private _tn = (_e get "town") getVariable ["cti_town_name", "un pueblo"];
			{[format ["Inteligencia: el enemigo esta bloqueando las entradas de %1 (barreras y coches ardiendo).", _tn]] remoteExec ["systemChat", _x]} forEach _hum;
		};
	};

	//--- pendientes de pueblos que ya tienen entrada (alguien estaba cerca o encima)
	{
		if (!(_x get "gone") && {count (_x get "todo") > 0} && {time >= (_x get "retry")}) then {[_x, _hum, _pl] call _fnc_try};
	} forEach VIOC_RB_LIST;

	//--- pueblos nuevos: primero los que te quito a ti, despues los mas cercanos a un jugador
	private _cands = [];
	private _keys = [];
	{
		private _t = _x;
		private _oi = VIOC_RB_OWN findIf {(_x select 0) isEqualTo _t};
		if (_oi >= 0) then {
			(VIOC_RB_OWN select _oi) params ["", "_sid", "_since", "_prev"];
			if ((_sid in _eids) && {(time - _since) >= VIOC_RB_DELAY} && {!(_t getVariable ["vioc_capital", false])} && {!([_t] call VIOC_RB_fnc_rear)} && {(VIOC_RB_LIST findIf {(_x get "town") isEqualTo _t}) < 0}) then {
				private _from = _prev in _hids;
				private _d = 1e6;
				{_d = _d min (_x distance2D _t)} forEach _pl;
				_keys pushBack [([1, 0] select _from) * 1e7 + _d, count _cands];
				_cands pushBack [_t, _sid, _from];
			};
		};
	} forEach _towns;
	_keys sort true;
	private _mineTowns = _towns select {(_x getVariable ["cti_town_sideID", -1]) in _hids};
	{
		if (({(count (_x get "cps")) + (count (_x get "todo")) > 0} count VIOC_RB_LIST) >= VIOC_RB_MAX_TOWNS) exitWith {};
		(_cands select (_x select 1)) params ["_t", "_sid", "_from"];
		if !([getPosATL _t, VIOC_RB_BUILD_FREE, _pl] call VIOC_RB_fnc_near) then {
			//--- ningun bloqueo pegado a un pueblo tuyo vecino
			private _spots = ([_t, VIOC_RB_N] call VIOC_TC_fnc_cpSpots) select {
				private _q = _x get "pos";
				(_mineTowns findIf {(_x distance2D _q) < 500}) < 0
			};
			private _e = createHashMapFromArray [["town", _t], ["sid", _sid], ["cps", []], ["todo", _spots], ["retry", 0], ["from", _from], ["told", false], ["gone", false]];
			VIOC_RB_LIST pushBack _e;
			[_e, _hum, _pl] call _fnc_try;
			diag_log format ["[VIOC enemy_roadblocks] %1 (%2): %3 bloqueos, %4 pendientes%5", _t getVariable ["cti_town_name", "?"], _sid, count (_e get "cps"), count (_e get "todo"), ["", ", te lo quito a ti"] select _from];
		};
	} forEach _keys;

	//--- coches: si un vehiculo de la IA que intenta moverse lleva VIOC_RB_STUCK s sin avanzar 3 m junto al coche, se quita
	//--- el coche (sin jugadores cerca ni mirando); lista para el fuego de los clientes
	private _burn = [];
	{
		{
			private _cp = _x;
			private _w = _cp getOrDefault ["wreck", objNull];
			if (!isNull _w) then {
				private _vs = ((getPosATL _w) nearEntities [["LandVehicle"], 12]) select {
					alive _x && {!isNull (driver _x)} && {({isPlayer _x} count (crew _x)) == 0}
					&& {!(unitReady (driver _x)) || {!(unitReady (effectiveCommander _x))}}
				};
				private _prev = _cp getOrDefault ["stkv", [objNull, [0, 0, 0]]];
				private _k = _vs findIf {_x isEqualTo (_prev select 0)};
				if (_k >= 0 && {((getPosATL (_vs select _k)) distance2D (_prev select 1)) < 3}) then {
					_cp set ["stk", (_cp getOrDefault ["stk", 0]) + VIOC_RB_PERIOD];
				} else {
					_cp set ["stk", ((_cp getOrDefault ["stk", 0]) - VIOC_RB_PERIOD) max 0];
					_cp set ["stkv", if (count _vs > 0) then {[_vs select 0, getPosATL (_vs select 0)]} else {[objNull, [0, 0, 0]]}];
				};
				if (((_cp get "stk") >= VIOC_RB_STUCK) && {[getPosATL _w, _pl] call VIOC_RB_fnc_hidden}) then {
					diag_log format ["[VIOC enemy_roadblocks] coche quitado en %1: %2 atascado alli", mapGridPosition (_cp get "pos"), typeOf ((_cp get "stkv") select 0)];
					deleteVehicle _w;
					_cp set ["wreck", objNull];
					_cp set ["stk", 0];
					VIOC_RB_INFO set [1, (VIOC_RB_INFO select 1) + 1];
				} else {
					_burn pushBack _w;
				};
			};
		} forEach (_x get "cps");
	} forEach VIOC_RB_LIST;
	if !(_burn isEqualTo VIOC_RB_BURN) then {
		VIOC_RB_BURN = _burn;
		publicVariable "VIOC_RB_BURN";
	};
	sleep VIOC_RB_PERIOD;
};

class VIOC_ENEMY_ROADBLOCKS {
	title = "VIOC: Bloqueos de la IA enemiga en las entradas de sus pueblos del frente (barreras y coche ardiendo en un carril)";
	values[] = {0,2,3};
	texts[] = {"No","2 por pueblo","3 por pueblo"};
	default = 2;
};
